{"tool":"write","path":"reports/export.py","content":""""Reports CSV exporter."""


_QUOTE_CHARS = (",", '"', "\r", "\n")


def _format_field(value):
    """Convert one CSV field to text with minimal RFC 4180 quoting."""
    if value is None:
        text = ""
    else:
        text = str(value)

    if any(char in text for char in _QUOTE_CHARS):
        return '"' + text.replace('"', '""') + '"'
    return text


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    ``columns`` may be any one-shot ordered iterable, including a generator.
    ``rows`` may likewise be a one-shot iterable of mappings. When no columns
    are selected, the header-only record is the full output.
    """
    column_list = list(columns)
    seen = set()
    for column in column_list:
        if not isinstance(column, str):
            raise ValueError("column names must be strings")
        if column in seen:
            raise ValueError("duplicate column name: {!r}".format(column))
        seen.add(column)

    if not column_list:
        return "\r\n"

    output = [",".join(column_list)]

    for row in rows:
        fields = []
        for column in column_list:
            try:
                value = row[column]
            except KeyError:
                value = None
            fields.append(_format_field(value))
        output.append(",".join(fields))

    return "\r\n".join(output) + "\r\n"
